25	export const runScenario = (scenario: Scenario): { results: Result[] } => {
26	  const { customer, steps } = scenario;
27	  const results: Result[] = [];
28	  const priorPayoutsByPolicy = new Map<number, number>();
29	  let contractIndex = 0;
30	
31	  steps.forEach((step) => {
32	    if (isQuoteStep(step)) {
33	      results.push({ premium: quote(customer, step.items, contractIndex) });
